// The host ABI's JS codecs and method descriptors, generated from the
// ABI model (host/gen/abi.json) by crates/hd_host_abi/tests/abi_model.rs.
// Do not edit: `HD_BLESS=1 cargo test -p hd_host_abi --test
// abi_model` rewrites it. host/wire.ts says how each value crosses.
import {
  bytes,
  data,
  handle,
  list,
  newtype,
  option,
  result,
  signed,
  signed64,
  str,
  tuple,
  unit,
  unsigned,
  unsigned64,
  variants,
} from "../wire.js";

// Each std type a host method crosses, from its declaration in lib/std.
export const JsonError = variants({
  UnexpectedEnd: { position: unsigned },
  UnexpectedCharacter: { position: unsigned },
  InvalidEscape: { position: unsigned },
  LoneSurrogate: { position: unsigned },
  ControlCharacter: { position: unsigned },
  NumberOutOfRange: { position: unsigned },
  NestingTooDeep: { position: unsigned },
  WrongType: { path: str, expected: str },
  MissingField: { path: str },
  DuplicateField: { path: str },
  UnknownVariant: { path: str, name: str },
});
export const FormError = variants({
  Unsupported: { field: str },
  Missing: { field: str },
  Invalid: { field: str, text: str },
});
export const BodyError = variants({
  Used: {},
  Json: { error: JsonError },
  Form: { error: FormError },
});
export const Path = newtype(str);
export const Command = data({
  program: str,
  args: list(str),
  env: list(tuple(str, str)),
  current_dir: option(Path),
  stdin: str,
});
export const ConsoleStream = variants({
  Stdout: {},
  Stderr: {},
  Stdin: {},
});
export const ConsoleError = variants({
  Closed: {},
  NotGranted: { stream: ConsoleStream },
  Other: { code: signed },
});
export const Datagram = data({
  bytes: bytes,
  host: str,
  port: unsigned,
});
export const Duration = data({
  millis: signed64,
});
export const EntryKind = variants({
  File: {},
  Directory: {},
  Symlink: {},
});
export const Timestamp = data({
  millis: signed64,
});
export const Entry = data({
  path: Path,
  kind: EntryKind,
  size: unsigned64,
  modified: option(Timestamp),
});
export const FsError = variants({
  NotFound: { path: Path },
  PermissionDenied: { path: Path },
  NotGranted: { path: Path },
  AlreadyExists: { path: Path },
  NotADirectory: { path: Path },
  IsADirectory: { path: Path },
  InvalidUtf8: { path: Path },
  Other: { message: str },
});
export const HostError = variants({
  NotGranted: { subject: str },
  Unsupported: { name: str },
  Other: { message: str },
  InvalidValue: { name: str, reason: str },
  Missing: { name: str },
});
export const Method = variants({
  Get: {},
  Head: {},
  Post: {},
  Put: {},
  Patch: {},
  Delete: {},
  Options: {},
  Other: { name: str },
});
export const NetError = variants({
  NotGranted: { address: str },
  InvalidAddress: { address: str },
  Dns: { host: str },
  Refused: { address: str },
  Timeout: {},
  Closed: {},
  Other: { message: str },
});
export const ProcessOutput = data({
  stdout: str,
  stderr: str,
  status: signed,
  program: str,
});
export const ProcessError = variants({
  NotFound: { program: str },
  PermissionDenied: { program: str },
  NotGranted: {},
  Other: { message: str },
  Exited: { output: ProcessOutput },
});
export const PropertyCase = data({
  example: option(unsigned),
  seed: signed64,
  size: signed,
  replay: list(signed64),
});
export const TcpListener = handle;
export const TcpStream = handle;
export const UdpSocket = handle;
export const WireResponse = data({
  status: unsigned,
  headers: list(tuple(str, str)),
  body: bytes,
  url: str,
});
export const WireHttpError = variants({
  NotGranted: { host: str },
  InvalidUrl: { url: str },
  Dns: { host: str },
  Connect: { message: str },
  Tls: { message: str },
  Timeout: {},
  TooManyRedirects: { url: str },
  Other: { message: str },
  Status: { response: WireResponse },
  InvalidHeader: { name: str },
  Body: { error: BodyError },
  InvalidContentEncoding: { encoding: str },
  OutputTooLarge: {},
  UnsupportedSetting: { name: str },
});
export const WireIdentity = data({
  certificate_chain: str,
  private_key: str,
});
export const WireRequest = data({
  method: Method,
  url: str,
  headers: list(tuple(str, str)),
  body: bytes,
  redirects: unsigned,
  dns_servers: option(list(str)),
  tls_roots: list(str),
  tls_identity: option(WireIdentity),
  connect_timeout: option(Duration),
  tls_handshake_timeout: option(Duration),
  response_header_timeout: option(Duration),
  body_read_timeout: option(Duration),
});

// Each host method by import module and name (crates/hd_run_wasmtime/DESIGN.md
// §17.2): `wait` is "never" for one import or "may" for `.start` and
// `.finish`; `resource` names the argument a grant checks; a scalar
// parameter or result is its Wasm type, any other a codec over the
// exchange buffer.
export const METHODS = {
  "hd:Console": {
    write_sync: {
      wait: "never",
      resource: null,
      params: [str],
      result: result(unit, ConsoleError),
    },
    write_error_sync: {
      wait: "never",
      resource: null,
      params: [str],
      result: result(unit, ConsoleError),
    },
  },
  "hd:ConsoleInput": {
    read_line: {
      wait: "may",
      resource: null,
      params: [],
      result: result(option(str), ConsoleError),
    },
    read_all: {
      wait: "may",
      resource: null,
      params: [],
      result: result(str, ConsoleError),
    },
  },
  "hd:Clock": {
    now: {
      wait: "never",
      resource: null,
      params: [],
      result: "i64",
    },
    monotonic: {
      wait: "never",
      resource: null,
      params: [],
      result: "i64",
    },
    sleep: {
      wait: "may",
      resource: null,
      params: ["i64"],
      result: "void",
    },
  },
  "hd:FsRead": {
    read_bytes: {
      wait: "may",
      resource: "path",
      params: [Path],
      result: result(bytes, FsError),
    },
    read_text: {
      wait: "may",
      resource: "path",
      params: [Path],
      result: result(str, FsError),
    },
    list_dir: {
      wait: "may",
      resource: "path",
      params: [Path],
      result: result(list(Entry), FsError),
    },
    stat: {
      wait: "may",
      resource: "path",
      params: [Path],
      result: result(option(Entry), FsError),
    },
  },
  "hd:FsWrite": {
    write_bytes: {
      wait: "may",
      resource: "path",
      params: [Path, bytes],
      result: result(unit, FsError),
    },
    write_text: {
      wait: "may",
      resource: "path",
      params: [Path, str],
      result: result(unit, FsError),
    },
    append_text: {
      wait: "may",
      resource: "path",
      params: [Path, str],
      result: result(unit, FsError),
    },
    create_dir_all: {
      wait: "may",
      resource: "path",
      params: [Path],
      result: result(unit, FsError),
    },
    remove: {
      wait: "may",
      resource: "path",
      params: [Path],
      result: result(unit, FsError),
    },
    rename: {
      wait: "may",
      resource: "path",
      params: [Path, Path],
      result: result(unit, FsError),
    },
    copy: {
      wait: "may",
      resource: "path",
      params: [Path, Path],
      result: result(unit, FsError),
    },
  },
  "hd:Random": {
    next_u64: {
      wait: "never",
      resource: null,
      params: [],
      result: "i64",
    },
    fill: {
      wait: "never",
      resource: null,
      params: ["i32"],
      result: bytes,
    },
  },
  "hd:Http": {
    send: {
      wait: "may",
      resource: "host",
      params: [WireRequest],
      result: result(WireResponse, WireHttpError),
    },
  },
  "hd:Net": {
    lookup: {
      wait: "may",
      resource: "host",
      params: [str],
      result: result(list(str), NetError),
    },
    connect: {
      wait: "may",
      resource: "addr",
      params: [str, "i32"],
      result: result(TcpStream, NetError),
    },
    listen: {
      wait: "may",
      resource: "addr",
      params: [str, "i32"],
      result: result(TcpListener, NetError),
    },
    bind_udp: {
      wait: "may",
      resource: "addr",
      params: [str, "i32"],
      result: result(UdpSocket, NetError),
    },
    "TcpStream.read": {
      wait: "may",
      resource: null,
      params: ["i32", "i32"],
      result: result(bytes, NetError),
    },
    "TcpStream.write": {
      wait: "may",
      resource: null,
      params: ["i32", bytes],
      result: result(unit, NetError),
    },
    "TcpStream.set_timeout": {
      wait: "never",
      resource: null,
      params: ["i32", option(Duration)],
      result: result(unit, NetError),
    },
    "TcpStream.set_nodelay": {
      wait: "never",
      resource: null,
      params: ["i32", "i32"],
      result: result(unit, NetError),
    },
    "TcpStream.set_keepalive": {
      wait: "never",
      resource: null,
      params: ["i32", option(Duration)],
      result: result(unit, NetError),
    },
    "TcpStream.close": {
      wait: "never",
      resource: null,
      params: ["i32"],
      result: result(unit, NetError),
    },
    "TcpStream.dispose": {
      wait: "may",
      resource: null,
      params: ["i32"],
      result: "void",
    },
    "TcpListener.accept": {
      wait: "may",
      resource: null,
      params: ["i32"],
      result: result(TcpStream, NetError),
    },
    "TcpListener.set_timeout": {
      wait: "never",
      resource: null,
      params: ["i32", option(Duration)],
      result: result(unit, NetError),
    },
    "TcpListener.local_address": {
      wait: "never",
      resource: null,
      params: ["i32"],
      result: result(tuple(str, unsigned), NetError),
    },
    "TcpListener.close": {
      wait: "never",
      resource: null,
      params: ["i32"],
      result: result(unit, NetError),
    },
    "TcpListener.dispose": {
      wait: "may",
      resource: null,
      params: ["i32"],
      result: "void",
    },
    "UdpSocket.send_to": {
      wait: "may",
      resource: "addr",
      params: ["i32", str, "i32", bytes],
      result: result(unit, NetError),
    },
    "UdpSocket.receive": {
      wait: "may",
      resource: null,
      params: ["i32", "i32"],
      result: result(Datagram, NetError),
    },
    "UdpSocket.set_timeout": {
      wait: "never",
      resource: null,
      params: ["i32", option(Duration)],
      result: result(unit, NetError),
    },
    "UdpSocket.local_address": {
      wait: "never",
      resource: null,
      params: ["i32"],
      result: result(tuple(str, unsigned), NetError),
    },
    "UdpSocket.close": {
      wait: "never",
      resource: null,
      params: ["i32"],
      result: result(unit, NetError),
    },
    "UdpSocket.dispose": {
      wait: "may",
      resource: null,
      params: ["i32"],
      result: "void",
    },
  },
  "hd:Process": {
    run: {
      wait: "may",
      resource: "program",
      params: [Command],
      result: result(ProcessOutput, ProcessError),
    },
  },
  "hd:Sys": {
    os: {
      wait: "never",
      resource: "sys-name",
      params: [],
      result: result(str, HostError),
    },
    arch: {
      wait: "never",
      resource: "sys-name",
      params: [],
      result: result(str, HostError),
    },
    hostname: {
      wait: "never",
      resource: "sys-name",
      params: [],
      result: result(str, HostError),
    },
    cpu_count: {
      wait: "never",
      resource: "sys-name",
      params: [],
      result: result(unsigned, HostError),
    },
  },
  "hd:Env": {
    get: {
      wait: "never",
      resource: "env-name",
      params: [str],
      result: option(str),
    },
    names: {
      wait: "never",
      resource: null,
      params: [],
      result: list(str),
    },
  },
  "hd:Args": {
    program: {
      wait: "never",
      resource: null,
      params: [],
      result: str,
    },
    list: {
      wait: "never",
      resource: null,
      params: [],
      result: list(str),
    },
  },
  "hd:TestRunner": {
    row: {
      wait: "never",
      resource: null,
      params: ["i32"],
      result: "i32",
    },
    report_timeout: {
      wait: "never",
      resource: null,
      params: ["i64"],
      result: "void",
    },
    snapshot_check: {
      wait: "never",
      resource: null,
      params: [str],
      result: str,
    },
    temp_dir: {
      wait: "never",
      resource: null,
      params: [],
      result: str,
    },
  },
  "hd:PropertyRunner": {
    start: {
      wait: "never",
      resource: null,
      params: ["i32", "i32", "i32"],
      result: PropertyCase,
    },
    record: {
      wait: "never",
      resource: null,
      params: ["i64"],
      result: "void",
    },
    show: {
      wait: "never",
      resource: null,
      params: [str],
      result: "void",
    },
  },
};

journal.js.source:
// The execution journal of a REPL session in the JS host, byte for byte as
// `hd_run` writes and reads it (crates/hd_run/src/journal.rs and
// replay.rs; docs/future-work/live-execution.md §4 and §5), so a journal the wasmtime
// session recorded replays here and one recorded here replays there.
//
// `journal = Header Row*`; `Row = kind: u8, index: uleb, len: uleb,
// payload, crc32: u32 LE`. The payload of each kind, the method naming of
// `Call` rows, the request (scalar parameters as uleb of their two's
// complement bits or 8 float bytes, then the exchange buffer bytes the call
// read, kept when 8 bytes or fewer and else as their digest) and the reply
// (a tag byte, the value, result bytes) are journal.rs's.
//
// Hashes are xxh3-128 with the default secret, as `hd_base::hash128`: an
// `Input` row holds the hash of the input's source text and of its module,
// and a request digest is the low half of the hash of the `StableHasher`
// tag `req` (its length as a u32, then its bytes) followed by the request.
//
// Values: integers that may pass 2^53 are bigints. A reply value is
// `{ tag: 0 }` (void), `{ tag: 1, v }` (an i64), `{ tag: 2, v }` (the bits
// of an f64) or `{ tag: 3, v, w }` (a status and a value, i32s). An end is
// `{ kind: "exit", status }`, or `{ kind }` with `trapped`, `stopped`,
// `cancelled` or `failed`.


















































const M64 = (1n << 64n) - 1n;
const utf8 = new TextEncoder();

// --- xxh3-128 (the scalar reference, seed 0) -----------------------------

const P32_1 = 0x9e3779b1n;
const P32_2 = 0x85ebca77n;
const P32_3 = 0xc2b2ae3dn;
const P64_1 = 0x9e3779b185ebca87n;
const P64_2 = 0xc2b2ae3d27d4eb4fn;
const P64_3 = 0x165667b19e3779f9n;
const P64_4 = 0x85ebca77c2b2ae63n;
const P64_5 = 0x27d4eb2f165667c5n;

// prettier-ignore
const SECRET = Uint8Array.of(
  0xb8, 0xfe, 0x6c, 0x39, 0x23, 0xa4, 0x4b, 0xbe, 0x7c, 0x01, 0x81, 0x2c, 0xf7, 0x21, 0xad, 0x1c,
  0xde, 0xd4, 0x6d, 0xe9, 0x83, 0x90, 0x97, 0xdb, 0x72, 0x40, 0xa4, 0xa4, 0xb7, 0xb3, 0x67, 0x1f,
  0xcb, 0x79, 0xe6, 0x4e, 0xcc, 0xc0, 0xe5, 0x78, 0x82, 0x5a, 0xd0, 0x7d, 0xcc, 0xff, 0x72, 0x21,
  0xb8, 0x08, 0x46, 0x74, 0xf7, 0x43, 0x24, 0x8e, 0xe0, 0x35, 0x90, 0xe6, 0x81, 0x3a, 0x26, 0x4c,
  0x3c, 0x28, 0x52, 0xbb, 0x91, 0xc3, 0x00, 0xcb, 0x88, 0xd0, 0x65, 0x8b, 0x1b, 0x53, 0x2e, 0xa3,
  0x71, 0x64, 0x48, 0x97, 0xa2, 0x0d, 0xf9, 0x4e, 0x38, 0x19, 0xef, 0x46, 0xa9, 0xde, 0xac, 0xd8,
  0xa8, 0xfa, 0x76, 0x3f, 0xe3, 0x9c, 0x34, 0x3f, 0xf9, 0xdc, 0xbb, 0xc7, 0xc7, 0x0b, 0x4f, 0x1d,
  0x8a, 0x51, 0xe0, 0x4b, 0xcd, 0xb4, 0x59, 0x31, 0xc8, 0x9f, 0x7e, 0xc9, 0xd9, 0x78, 0x73, 0x64,
  0xea, 0xc5, 0xac, 0x83, 0x34, 0xd3, 0xeb, 0xc3, 0xc5, 0x81, 0xa0, 0xff, 0xfa, 0x13, 0x63, 0xeb,
  0x17, 0x0d, 0xdd, 0x51, 0xb7, 0xf0, 0xda, 0x49, 0xd3, 0x16, 0x55, 0x26, 0x29, 0xd4, 0x68, 0x9e,
  0x2b, 0x16, 0xbe, 0x58, 0x7d, 0x47, 0xa1, 0xfc, 0x8f, 0xf8, 0xb8, 0xd1, 0x7a, 0xd0, 0x31, 0xce,
  0x45, 0xcb, 0x3a, 0x8f, 0x95, 0x16, 0x04, 0x28, 0xaf, 0xd7, 0xfb, 0xca, 0xbb, 0x4b, 0x40, 0x7e,
);
const SV = new DataView(SECRET.buffer);

const add = (a        , b        )         => (a + b) & M64;
const mul = (a        , b        )         => (a * b) & M64;
const neg = (a        )         => -a & M64;
const xorshift = (v        , s        )         => v ^ (v >> s);
const mul128 = (a        , b        )                   => {
  const p = a * b;
  return [p & M64, p >> 64n];
};
const fold = (a        , b        )         => {
  const p = a * b;
  return (p & M64) ^ (p >> 64n);
};
const bswap64 = (v        )         => {
  let r = 0n;
  for (let i = 0; i < 8; i++) {
    r = (r << 8n) | ((v >> BigInt(8 * i)) & 0xffn);
  }
  return r;
};
const bswap32 = (v        )         =>
  ((v & 0xff) << 24) | ((v & 0xff00) << 8) | ((v >>> 8) & 0xff00) | (v >>> 24);
const avalanche = (v        )         => xorshift(mul(xorshift(v, 37n), 0x165667919e3779f9n), 32n);
const avalanche64 = (v        )         => {
  v = mul(xorshift(v, 33n), P64_2);
  v = mul(xorshift(v, 29n), P64_3);
  return xorshift(v, 32n);
};
const s64 = (at        )         => SV.getBigUint64(at, true);
const s32 = (at        )         => BigInt(SV.getUint32(at, true));
const join128 = (lo        , hi        )         => lo | (hi << 64n);

function short128(b            , dv          )         {
  const len = b.length;
  const r64 = (at        )         => dv.getBigUint64(at, true);
  if (len > 8) {
    const lo = r64(0);
    let hi = r64(len - 8);
    let [ml, mh] = mul128(lo ^ hi ^ (s64(32) ^ s64(40)), P64_1);
    ml = add(ml, BigInt(len - 1) << 54n);
    hi ^= s64(48) ^ s64(56);
    mh = add(mh, add(hi, (hi & 0xffffffffn) * (P32_2 - 1n)));
    ml ^= bswap64(mh);
    const [rl, rh] = mul128(ml, P64_2);
    return join128(avalanche(rl), avalanche(add(rh, mul(mh, P64_2))));
  }
  if (len >= 4) {
    const input = BigInt(dv.getUint32(0, true)) + (BigInt(dv.getUint32(len - 4, true)) << 32n);
    let [lo, hi] = mul128(input ^ (s64(16) ^ s64(24)), add(P64_1, BigInt(len) << 2n));
    hi = add(hi, (lo << 1n) & M64);
    lo ^= hi >> 3n;
    lo = xorshift(mul(xorshift(lo, 35n), 0x9fb21c651e98df25n), 28n);
    return join128(lo, avalanche(hi));
  }
  if (len > 0) {
    const lo32 = ((b[0]  << 16) | (b[len >> 1]  << 24) | b[len - 1]  | (len << 8)) >>> 0;
    const swapped = bswap32(lo32) >>> 0;
    const hi32 = ((swapped << 13) | (swapped >>> 19)) >>> 0;
    const lo = avalanche64(BigInt(lo32) ^ (s32(0) ^ s32(4)));
    const hi = avalanche64(BigInt(hi32) ^ (s32(8) ^ s32(12)));
    return join128(lo, hi);
  }
  return join128(avalanche64(s64(64) ^ s64(72)), avalanche64(s64(80) ^ s64(88)));
}

function mid128(b            , dv          )         {
  const len = b.length;
  const r64 = (at        )         => dv.getBigUint64(at, true);
  const mix16 = (at        , sat        )         =>
    fold(r64(at) ^ s64(sat), r64(at + 8) ^ s64(sat + 8));
  let a0 = mul(BigInt(len), P64_1);
  let a1 = 0n;
  const mix32 = (at1        , at2        , sat        )       => {
    a0 = add(a0, mix16(at1, sat)) ^ add(r64(at2), r64(at2 + 8));
    a1 = add(a1, mix16(at2, sat + 16)) ^ add(r64(at1), r64(at1 + 8));
  };
  if (len <= 128) {
    if (len > 32) {
      if (len > 64) {
        if (len > 96) {
          mix32(48, len - 64, 96);
        }
        mix32(32, len - 48, 64);
      }
      mix32(16, len - 32, 32);
    }
    mix32(0, len - 16, 0);
  } else {
    for (let i = 0; i < 4; i++) {
      mix32(32 * i, 32 * i + 16, 32 * i);
    }
    a0 = avalanche(a0);
    a1 = avalanche(a1);
    const rounds = Math.floor(len / 32);
    for (let i = 4; i < rounds; i++) {
      mix32(32 * i, 32 * i + 16, 3 + 32 * (i - 4));
    }
    mix32(len - 16, len - 32, 136 - 17 - 16);
  }
  const lo = add(a0, a1);
  const hi = add(add(mul(a0, P64_1), mul(a1, P64_4)), mul(BigInt(len), P64_2));
  return join128(avalanche(lo), neg(avalanche(hi)));
}

function long128(b            , dv          )         {
  const len = b.length;
  const acc = [P32_3, P64_1, P64_2, P64_3, P64_4, P32_2, P64_5, P32_1];
  const stripe = (at        , sat        )       => {
    for (let i = 0; i < 8; i++) {
      const data = dv.getBigUint64(at + 8 * i, true);
      const key = data ^ s64(sat + 8 * i);
      acc[i ^ 1] = add(acc[i ^ 1] , data);
      acc[i] = add(acc[i] , (key & 0xffffffffn) * (key >> 32n));
    }
  };
  const blockLen = 64 * 16;
  const blocks = Math.floor((len - 1) / blockLen);
  for (let n = 0; n < blocks; n++) {
    for (let s = 0; s < 16; s++) {
      stripe(n * blockLen + 64 * s, 8 * s);
    }
    for (let i = 0; i < 8; i++) {
      acc[i] = mul(xorshift(acc[i] , 47n) ^ s64(128 + 8 * i), P32_1);
    }
  }
  const stripes = Math.floor((len - 1 - blockLen * blocks) / 64);
  for (let s = 0; s < stripes; s++) {
    stripe(blocks * blockLen + 64 * s, 8 * s);
  }
  stripe(len - 64, 192 - 64 - 7);
  const merge = (sat        , start        )         => {
    let r = start;
    for (let i = 0; i < 4; i++) {
      r = add(r, fold(acc[2 * i]  ^ s64(sat + 16 * i), acc[2 * i + 1]  ^ s64(sat + 16 * i + 8)));
    }
    return avalanche(r);
  };
  return join128(merge(11, mul(BigInt(len), P64_1)), merge(117, ~mul(BigInt(len), P64_2) & M64));
}

// The xxh3-128 hash of `bytes`, as a bigint (`hd_base::hash128`).
export function xxh3_128(bytes            )         {
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (bytes.length <= 16) {
    return short128(bytes, dv);
  }
  if (bytes.length <= 240) {
    return mid128(bytes, dv);
  }
  return long128(bytes, dv);
}

// --- framing ---------------------------------------------------------------

const CRC_TABLE = Array.from({ length: 256 }, (_, i) => {
  let c = i;
  for (let bit = 0; bit < 8; bit++) {
    c = c & 1 ? (c >>> 1) ^ 0xedb88320 : c >>> 1;
  }
  return c >>> 0;
});

// CRC-32 (IEEE), the journal checksum.
export function crc32(bytes            )         {
  let c = 0xffffffff;
  for (const b of bytes) {
    c = CRC_TABLE[(c ^ b) & 0xff]  ^ (c >>> 8);
  }
  return ~c >>> 0;
}

// A growable byte string that rows and payloads are written into.
class Bytes {
  buf            ;
  len        ;

  constructor() {
    this.buf = new Uint8Array(256);
    this.len = 0;
  }
  room(n        )       {
    if (this.len + n <= this.buf.length) {
      return;
    }
    const next = new Uint8Array(Math.max(this.buf.length * 2, this.len + n));
    next.set(this.buf.subarray(0, this.len));
    this.buf = next;
  }
  byte(b        )       {
    this.room(1);
    this.buf[this.len++] = b;
  }
  raw(bytes            )       {
    this.room(bytes.length);
    this.buf.set(bytes, this.len);
    this.len += bytes.length;
  }
  uleb(v                 )       {
    let x = BigInt(v);
    this.room(10);
    do {
      let b = Number(x & 0x7fn);
      x >>= 7n;
      if (x) {
        b |= 0x80;
      }
      this.buf[this.len++] = b;
    } while (x);
  }
  // A u64 or u128 as `bytes` little-endian bytes.
  le(v                 , bytes        )       {
    for (let i = 0; i < bytes; i++) {
      this.byte(Number((BigInt(v) >> BigInt(8 * i)) & 0xffn));
    }
  }
  view()             {
    return this.buf.subarray(0, this.len);
  }
  clear()       {
    this.len = 0;
  }
}

const ulebLen = (v                 )         => {
  let n = 1;
  for (let x = BigInt(v) >> 7n; x; x >>= 7n) {
    n++;
  }
  return n;
};

// Row kinds, as journal.rs numbers them.
export const KIND = {
  header: 0,
  input: 1,
  call: 2,
  finish: 3,
  wake: 4,
  block: 5,
  abort: 6,
  cancel: 7,
  end: 8,
}         ;
const KIND_NAMES = Object.keys(KIND)                         ;

// The format number of a `Header` row.
export const FORMAT = 1;
// A REPL session's journal cap: past it, recording stops.
export const SESSION_CAP = 64 << 20;

function appendRow(out       , kind        , index        , payload            )       {
  const start = out.len;
  out.byte(kind);
  out.uleb(index);
  out.uleb(payload.length);
  out.raw(payload);
  out.le(crc32(out.buf.subarray(start, out.len)), 4);
}

// A reader over a payload; every read answers `undefined` past its end.
class Reader {
  b            ;
  at        ;

  constructor(b            ) {
    this.b = b;
    this.at = 0;
  }
  uleb()                     {
    let v = 0n;
    for (let shift = 0n; shift < 64n; shift += 7n) {
      const byte = this.b[this.at];
      if (byte === undefined) {
        return undefined;
      }
      this.at++;
      v |= BigInt(byte & 0x7f) << shift;
      if (!(byte & 0x80)) {
        return v;
      }
    }
    return undefined;
  }
  num()                     {
    const v = this.uleb();
    return v === undefined || v > 0xffffffffn ? undefined : Number(v);
  }
  bytes(n                    )                         {
    if (n === undefined || this.at + n > this.b.length) {
      return undefined;
    }
    const out = this.b.slice(this.at, this.at + n);
    this.at += n;
    return out;
  }
  le(n        )                     {
    const b = this.bytes(n);
    if (b === undefined) {
      return undefined;
    }
    let v = 0n;
    for (let i = n - 1; i >= 0; i--) {
      v = (v << 8n) | BigInt(b[i] );
    }
    return v;
  }
  text()                     {
    const b = this.bytes(this.num());
    if (b === undefined) {
      return undefined;
    }
    try {
      return new TextDecoder("utf-8", { fatal: true }).decode(b);
    } catch {
      return undefined;
    }
  }
  handles()                       {
    const n = this.num();
    if (n === undefined) {
      return undefined;
    }
    const out           = [];
    for (let i = 0; i < n; i++) {
      const h = this.num();
      if (h === undefined) {
        return undefined;
      }
      out.push(h);
    }
    return out;
  }
}

// Reads rows until the end or the first torn or corrupt row: the rows,
// `{ kind, index, payload }`, and the length of the valid prefix.
export function readRows(b            )                                 {
  const rows        = [];
  let at = 0;
  for (;;) {
    const start = at;
    if (at >= b.length) {
      return { rows, valid: start };
    }
    const r = new Reader(b);
    r.at = at + 1;
    const kind = b[at] ;
    const index = r.uleb();
    const len = r.num();
    const payload = r.bytes(len);
    const crc = r.le(4);
    if (
      kind >= KIND_NAMES.length ||
      payload === undefined ||
      crc === undefined ||
      Number(crc) !== crc32(b.subarray(start, r.at - 4)) ||
      index !== BigInt(rows.length)
    ) {
      return { rows, valid: start };
    }
    rows.push({ kind, index: Number(index), payload });
    at = r.at;
  }
}

// The digest of a request's argument bytes (`journal::request_digest`).
export function requestDigest(args            )         {
  const tagged = new Uint8Array(7 + args.length);
  tagged.set([3, 0, 0, 0, 0x72, 0x65, 0x71]);
  tagged.set(args, 7);
  return xxh3_128(tagged) & M64;
}

// The request a `Call` row holds for the arguments `args`.
export const requestOf = (args            )          =>
  args.length <= 8
    ? { args: Uint8Array.from(args) }
    : { len: args.length, digest: requestDigest(args) };

const sameRequest = (a         , b         )          =>
  "args" in a && "args" in b
    ? a.args.length === b.args.length && a.args.every((x, i) => x === b.args[i])
    : "len" in a && "len" in b && a.len === b.len && a.digest === b.digest;

// Appends an integer parameter to a call's arguments.
export function putIntArg(out       , v                 )       {
  out.uleb(BigInt.asUintN(64, BigInt(v)));
}

// A host call's arguments as a journal holds them: each scalar parameter
// in `values` by its type in `types` (integers as `putIntArg`, floats as
// their IEEE 754 bits, an `f32` widened to 8 bytes), then `tail`, the
// exchange buffer bytes the call reads, when not null.
export function callArgs(
  values                              ,
  types                   ,
  tail                   ,
)             {
  const out = new Bytes();
  const dv = new DataView(new ArrayBuffer(8));
  values.forEach((v, i) => {
    const type = types[i];
    if (type === "i32" || type === "i64") {
      putIntArg(out, v);
    } else if (type === "f64") {
      dv.setFloat64(0, Number(v), true);
      out.raw(new Uint8Array(dv.buffer));
    } else if (type === "f32") {
      dv.setFloat32(0, Number(v), true);
      out.le(BigInt(dv.getUint32(0, true)), 8);
    }
  });
  if (tail) {
    out.raw(tail);
  }
  return out.view().slice();
}

function putReply(out       , value       , result                   )       {
  out.byte(value.tag | (result ? 4 : 0));
  if (value.tag === 1) {
    out.uleb(BigInt.asUintN(64, BigInt(value.v)));
  } else if (value.tag === 2) {
    out.le(value.v, 8);
  } else if (value.tag === 3) {
    out.uleb(value.v >>> 0);
    out.uleb(value.w >>> 0);
  }
  if (result) {
    out.uleb(result.length);
    out.raw(result);
  }
}

function getReply(r        )                                                          {
  const tag = r.bytes(1)?.[0];
  if (tag === undefined) {
    return undefined;
  }
  const low = (v                    )                     =>
    v === undefined ? undefined : Number(BigInt.asIntN(32, v));
  let value       ;
  switch (tag & 3) {
    case 0:
      value = { tag: 0 };
      break;
    case 1: {
      const v = r.uleb();
      if (v === undefined) {
        return undefined;
      }
      value = { tag: 1, v: BigInt.asIntN(64, v) };
      break;
    }
    case 2: {
      const v = r.le(8);
      if (v === undefined) {
        return undefined;
      }
      value = { tag: 2, v };
      break;
    }
    default: {
      const v = low(r.uleb());
      const w = low(r.uleb());
      if (v === undefined || w === undefined) {
        return undefined;
      }
      value = { tag: 3, v, w };
    }
  }
  let result                    = null;
  if (tag >> 2 === 1) {
    const bytes = r.bytes(r.num());
    if (bytes === undefined) {
      return undefined;
    }
    result = bytes;
  } else if (tag >> 2 !== 0) {
    return undefined;
  }
  return { value, result };
}

const END_KINDS                = ["exit", "trapped", "stopped", "cancelled", "failed"];

function getRequest(r        , len        )                      {
  if (len <= 8n) {
    const args = r.bytes(Number(len));
    return args === undefined ? undefined : { args };
  }
  const digest = r.le(8);
  return digest === undefined ? undefined : { len: Number(len), digest };
}

function decodeCall(
  r        ,
  methods                          ,
)                                      {
  const method = r.num();
  if (method === methods.length) {
    methods.push([r.text(), r.text()]);
  }
  if (method === undefined) {
    return undefined;
  }
  const named = methods[method];
  if (!named || named.includes(undefined)) {
    return undefined;
  }
  const len = r.uleb();
  if (len === undefined) {
    return undefined;
  }
  const request = getRequest(r, len);
  const reply = getReply(r);
  if (!request || !reply) {
    return undefined;
  }
  return { kind: "call", module: named[0] , name: named[1] , request, ...reply };
}

function decodeFinish(r        )                                      {
  const handle = r.num();
  const reply = getReply(r);
  return reply ? { kind: "finish", handle, ...reply } : undefined;
}

function decodeEnd(r        )                                      {
  const tag = r.bytes(1)?.[0];
  if (tag === undefined || tag >= END_KINDS.length) {
    return undefined;
  }
  if (tag === 0) {
    const status = r.bytes(1)?.[0];
    return status === undefined ? undefined : { kind: "end", end: { kind: "exit", status } };
  }
  return {
    kind: "end",
    end: { kind: END_KINDS[tag]                                  },
  };
}

function decodeRow(row     , methods                          )                    {
  const r = new Reader(row.payload);
  let event                                     ;
  switch (row.kind) {
    case KIND.header:
      event = { kind: "header", format: r.uleb(), execution: r.bytes(16) };
      break;
    case KIND.input:
      event = { kind: "input", number: r.num(), source: r.le(16), module: r.le(16) };
      break;
    case KIND.call:
      event = decodeCall(r, methods);
      break;
    case KIND.finish:
      event = decodeFinish(r);
      break;
    case KIND.wake:
      event = { kind: "wake", poll: r.uleb(), handles: r.handles() };
      break;
    case KIND.block:
      event = { kind: "block", handles: r.handles() };
      break;
    case KIND.abort:
      event = { kind: "abort", handle: r.num() };
      break;
    case KIND.cancel:
      event = { kind: "cancel", poll: r.uleb() };
      break;
    default:
      event = decodeEnd(r);
  }
  if (!event || Object.values(event).includes(undefined) || r.at !== row.payload.length) {
    return undefined;
  }
  return event                    ;
}

// Decodes the rows of one journal, in order, or throws naming the first
// row whose payload does not decode.
export function decodeRows(rows       )          {
  const methods                           = [];
  return rows.map((row) => {
    const event = decodeRow(row, methods);
    if (!event) {
      const kind = KIND_NAMES[row.kind] ;
      throw new Error(
        `row ${row.index} (${kind[0].toUpperCase()}${kind.slice(1)}) does not decode`,
      );
    }
    return event;
  });
}

// --- the recorder ------------------------------------------------------------

// Writes one execution's journal in memory, as `journal::Recorder` does:
// the host's import call sites call `call`, `finish`, `block` or `abort`
// per host call; the driver `poll`, `wake` and `cancel`; a session `input`
// and `end` around each input. Past its cap, recording stops for good and
// the journal is dropped; `takeNotice` then answers true once.
export class Recorder {
  bytes       ;
  capBytes        ;
  next        ;
  methods                     ;
  row       ;
  polls        ;
  state                       ;

  // `execution` is the 16 bytes of the execution id.
  constructor(cap        , execution            ) {
    this.bytes = new Bytes();
    this.capBytes = cap;
    this.next = 0;
    this.methods = new Map();
    this.row = new Bytes();
    this.polls = 0;
    this.state = "on";
    this.row.uleb(FORMAT);
    this.row.raw(execution);
    this.push(KIND.header);
  }
  // The journal so far, or `null` once recording stopped at the cap.
  journal()                    {
    return this.state === "on" ? this.bytes.view() : null;
  }
  get cap()         {
    return this.capBytes;
  }
  setCap(cap        )       {
    this.capBytes = cap;
  }
  takeNotice()          {
    if (this.state !== "off") {
      return false;
    }
    this.state = "told";
    return true;
  }
  // A host call of the import `module` `name` with the arguments
  // `request` that returned `value` and, when not null, `result` bytes.
  call({
    module,
    name,
    request,
    value,
    result,
  }   





   )       {
    if (this.state !== "on") {
      return;
    }
    const key = `${module}\0${name}`;
    const known = this.methods.get(key);
    if (known === undefined) {
      this.row.uleb(this.methods.size);
      for (const text of [module, name]) {
        const b = utf8.encode(text);
        this.row.uleb(b.length);
        this.row.raw(b);
      }
      this.methods.set(key, this.methods.size);
    } else {
      this.row.uleb(known);
    }
    this.row.uleb(request.length);
    if (request.length <= 8) {
      this.row.raw(request);
    } else {
      this.row.le(requestDigest(request), 8);
    }
    putReply(this.row, value, result);
    this.push(KIND.call);
  }
  finish(handle        , value       , result                   )       {
    if (this.state !== "on") {
      return;
    }
    this.row.uleb(handle);
    putReply(this.row, value, result);
    this.push(KIND.finish);
  }
  block(handles                   )       {
    if (this.state !== "on") {
      return;
    }
    this.handles(handles);
    this.push(KIND.block);
  }
  abort(handle        )       {
    if (this.state !== "on") {
      return;
    }
    this.row.uleb(handle);
    this.push(KIND.abort);
  }
  poll()       {
    this.polls += 1;
  }
  wake(handles                   )       {
    if (this.state !== "on") {
      return;
    }
    this.row.uleb(this.polls);
    this.handles(handles);
    this.push(KIND.wake);
  }
  cancel()       {
    if (this.state !== "on") {
      return;
    }
    this.row.uleb(this.polls);
    this.push(KIND.cancel);
  }
  // A REPL input numbered `number` starts, with its source text (a
  // string) and module bytes.
  input(number        , source        , module            )       {
    this.polls = 0;
    if (this.state !== "on") {
      return;
    }
    this.row.uleb(number);
    this.row.le(xxh3_128(utf8.encode(source)), 16);
    this.row.le(xxh3_128(module), 16);
    this.push(KIND.input);
  }
  end(end     )       {
    if (this.state !== "on") {
      return;
    }
    this.row.byte(END_KINDS.indexOf(end.kind));
    if (end.kind === "exit") {
      this.row.byte(end.status);
    }
    this.push(KIND.end);
  }
          handles(handles                   )       {
    this.row.uleb(handles.length);
    for (const h of handles) {
      this.row.uleb(h);
    }
  }
          push(kind        )       {
    const len = this.row.len;
    const size = 1 + ulebLen(this.next) + ulebLen(len) + len + 4;
    if (this.bytes.len + size > this.capBytes) {
      this.state = "off";
      this.bytes = new Bytes();
      this.methods = new Map();
      this.row = new Bytes();
      return;
    }
    appendRow(this.bytes, kind, this.next, this.row.view());
    this.next += 1;
    this.row.clear();
  }
}

// --- replay ------------------------------------------------------------------

// A row, as a divergence message names what the record has.
function describe(event                   )         {
  switch (event?.kind) {
    case undefined:
      return "nothing more";
    case "header":
      return "a header";
    case "input":
      return `input ${event.number}`;
    case "call":
      return `a call of ${event.module} ${event.name}`;
    case "finish":
      return `the finish of operation ${event.handle}`;
    case "wake":
      return `a wake after ${event.poll} polls`;
    case "block":
      return "a block";
    case "abort":
      return `the abort of operation ${event.handle}`;
    case "cancel":
      return "a cancel";
    case "end":
      return `its end: it ${ended(event.end)}`;
  }
}

// How an input ended, as a sentence's verb phrase.
export function ended(end     )         {
  switch (end.kind) {
    case "exit":
      return end.status === 0 ? "ended" : `ended with status ${end.status}`;
    case "trapped":
      return "panicked";
    case "stopped":
      return "was stopped";
    case "cancelled":
      return "was cancelled";
    default:
      return "failed to run";
  }
}

const sameEnd = (a     , b     )          => a.kind === b.kind && a.status === b.status;

// Reads a session's journal into its execution id (16 bytes) and its
// inputs, `{ number, source, module, events, end }` with `end` null when
// the journal ends inside it. A torn tail is cut.
export function recorded(bytes            )   


  {
  const events = decodeRows(readRows(bytes).rows);
  const header = events.shift();
  if (header?.kind !== "header") {
    throw new Error("the journal has no header");
  }
  if (header.format !== BigInt(FORMAT)) {
    throw new Error(`the journal has format ${header.format}, not ${FORMAT}`);
  }
  const inputs                  = [];
  for (const event of events) {
    if (event.kind === "input") {
      const { number, source, module } = event;
      inputs.push({ number, source, module, events: [], end: null });
      continue;
    }
    const input = inputs.at(-1);
    if (!input || input.end) {
      throw new Error(`the journal has ${describe(event)} outside an input`);
    }
    if (event.kind === "end") {
      input.end = event.end;
    } else {
      input.events.push(event);
    }
  }
  return { execution: header.execution, inputs };
}

function archivedCall(
  event                                  ,
  methods                     ,
)             {
  const write = new Bytes();
  const key = `${event.module}\0${event.name}`;
  const known = methods.get(key);
  write.uleb(known ?? methods.size);
  if (known === undefined) {
    for (const text of [event.module, event.name]) {
      const encoded = utf8.encode(text);
      write.uleb(encoded.length);
      write.raw(encoded);
    }
    methods.set(key, methods.size);
  }
  if ("args" in event.request) {
    write.uleb(event.request.args.length);
    write.raw(event.request.args);
  } else {
    write.uleb(event.request.len);
    write.le(event.request.digest, 8);
  }
  putReply(write, event.value, event.result);
  return write.view();
}

// Materializes archived, completed epochs as one ordinary journal. Method
// numbers and row indices are local to each chunk and must be reassigned;
// stored request digests and reply bytes are copied without running HD.
export function joinJournals(chunks                      )             {
  const out = new Bytes();
  const methods = new Map                ();
  let execution                    = null;
  let next = 0;
  let last = -1;
  for (const bytes of chunks) {
    const read = readRows(bytes);
    if (read.valid !== bytes.byteLength) {
      throw new Error("an archived journal is cut short");
    }
    const record = recorded(bytes);
    if (record.inputs.some((input) => input.end === null)) {
      throw new Error("an archived journal has an unfinished input");
    }
    if (execution && !execution.every((b, i) => b === record.execution[i])) {
      throw new Error("archived journals belong to different executions");
    }
    const events = decodeRows(read.rows);
    for (const [index, event] of events.entries()) {
      const row = read.rows[index] ;
      if (event.kind === "header") {
        if (execution) {
          continue;
        }
        execution = record.execution;
      }
      if (event.kind === "input") {
        if (event.number <= last) {
          throw new Error("archived inputs are not in increasing order");
        }
        last = event.number;
      }
      let payload = row.payload;
      if (event.kind === "call") {
        payload = archivedCall(event, methods);
      }
      appendRow(out, row.kind, next++, payload);
    }
  }
  if (!execution) {
    throw new Error("no archived journal header");
  }
  return out.view();
}

// Whether `source` is the text a recorded input ran, by its hash.
export const ran = (input               , source        )          =>
  xxh3_128(utf8.encode(source)) === input.source;

// The divergence of a replayed input: the message, as `Replay` words it.
export class Diverged extends Error {}

// Serves one recorded input's host results while it runs again
// (`replay::Replay`): each method throws `Diverged` at the first request
// that is not the record's next row, and keeps its message.
export class Replay {
           number        ;
          events         ;
          polls        ;
  diverged               ;

  constructor(input               ) {
    this.number = input.number;
    this.events = [...input.events];
    this.polls = 0;
    this.diverged = null;
  }
  // The reply `{ value, result }` the record holds for a call of `module`
  // `name` with the arguments `args`.
  call(
    module        ,
    name        ,
    args            ,
  )                                              {
    const asked = `called ${module} ${name}`;
    const front = this.events[0];
    if (front?.kind === "call" && front.module === module && front.name === name) {
      if (!sameRequest(front.request, requestOf(args))) {
        this.diverge(`input ${this.number} ${asked} with other arguments than before`);
      }
      const event = this.events.shift()                                     ;
      return { value: event.value, result: event.result };
    }
    return this.unexpected(asked);
  }
  finish(handle        )                                              {
    const front = this.events[0];
    if (front?.kind === "finish" && front.handle === handle) {
      this.events.shift();
      return { value: front.value, result: front.result };
    }
    return this.unexpected(`finished operation ${handle}`);
  }
  // The handles of a recorded block, or null when the record has nothing
  // more (the block finds nothing pending, as the first run's did).
  block()                  {
    const front = this.events[0];
    if (front === undefined) {
      return null;
    }
    if (front.kind === "block") {
      this.events.shift();
      return front.handles;
    }
    return this.unexpected("blocked");
  }
  abort(handle        )       {
    const front = this.events[0];
    if (front?.kind === "abort" && front.handle === handle) {
      this.events.shift();
    } else {
      this.unexpected(`aborted operation ${handle}`);
    }
  }
  poll()       {
    this.polls += 1;
  }
  // Whether the record's next row is a wake: the input waits for one.
  wakeNext()          {
    return this.events[0]?.kind === "wake";
  }
  // The handles the record wakes the input with after its polls so far.
  wake()           {
    const front = this.events[0];
    if (front?.kind === "wake" && front.poll === BigInt(this.polls)) {
      this.events.shift();
      return front.handles;
    }
    return this.unexpected(`waited on the host after ${this.polls} polls`);
  }
  // The input ended with `end`: a divergence unless the record ended it
  // so, `recordedEnd`, after every row was served.
  end(end     , recordedEnd            )       {
    if (this.diverged !== null) {
      throw new Diverged(this.diverged);
    }
    if (this.events.length) {
      this.unexpected(`${ended(end)} early`);
    }
    if (recordedEnd === null) {
      this.diverge(`input ${this.number} ${ended(end)}, but the record of it is cut short`);
    }
    if (!sameEnd(end, recordedEnd)) {
      this.diverge(`input ${this.number} ${ended(end)}, but before it ${ended(recordedEnd)}`);
    }
  }
          unexpected(asked        )        {
    return this.diverge(
      `input ${this.number} ${asked}, but the record has ${describe(this.events[0])}`,
    );
  }
          diverge(message        )        {
    this.diverged ??= message;
    throw new Diverged(this.diverged);
  }
}

// --- import types --------------------------------------------------------------

// The parameter and result types of each function a module imports, by
// `module\0name`: "i32", "i64", "f32", "f64" or "ref". A recorder encodes
// parameters by them and a replay converts served values to them.
export function importTypes(bytes                          )                                 {
  const b = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  const r = new Reader(b);
  r.at = 8;
  const types               = [];
  const out = new Map                           ();
  const NUM                         = {
    0x7f: "i32",
    0x7e: "i64",
    0x7d: "f32",
    0x7c: "f64",
    0x7b: "v128",
  };
  const sleb = ()         => {
    let shift = 0;
    let byte        ;
    do {
      byte = b[r.at++] ;
      shift += 7;
    } while (byte & 0x80);
    return shift;
  };
  const valtype = ()         => {
    const t = b[r.at++] ;
    if (NUM[t]) {
      return NUM[t];
    }
    if (t === 0x63 || t === 0x64) {
      sleb();
    }
    return "ref";
  };
  const vec =    (each         )      => Array.from({ length: r.num() ?? 0 }, each);
  // A memory's or table's limits: flags, the minimum, and the maximum
  // when flag bit 0 is set.
  const limits = ()       => {
    const flags = r.num() ?? 0;
    r.num();
    if (flags & 1) {
      r.num();
    }
  };
  const functionType = ()       => {
    if (b[r.at++] !== 0x60) {
      throw new Error("a module type is not a function");
    }
    types.push({ params: vec(valtype), results: vec(valtype) });
  };
  while (r.at < b.length) {
    const id = b[r.at++] ;
    const size = r.num() ?? 0;
    const end = r.at + size;
    if (id === 1) {
      vec(functionType);
    } else if (id === 2) {
      vec(() => {
        const module = r.text() ;
        const name = r.text() ;
        const kind = b[r.at++] ;
        if (kind === 0x00) {
          out.set(`${module}\0${name}`, types[r.num() ] ?? null);
        } else if (kind === 0x02) {
          limits();
        } else if (kind === 0x01) {
          valtype();
          limits();
        } else if (kind === 0x03) {
          valtype();
          r.at++;
        } else {
          r.at++;
          r.num();
        }
      });
      return out;
    }
    r.at = end;
  }
  return out;
}

